"💡 Верно. Вальс считают раз-два-три": "💡 Тоғра. Вальсни бир-икки-үч дәп санайду",
"💡 Верно. Две восьмые — это один счёт": "💡 Тоғра. Икки сәккизлик — бир һесап",
"💡 Верно. Динамика — громкость музыки": "💡 Тоғра. Динамика — музикиниң қаттиқлиғи",
"💡 Верно. Звуки идут один за другим разной длины": "💡 Тоғра. Авазлар узунлуғи һәр хил болуп бир-биридин кейин кәлгән",
"💡 Верно. Звукоряд: до, ре, ми, фа, соль, ля, си": "💡 Тоғра. Аваз қатари: до, ре, ми, фа, соль, ля, си",
"💡 Верно. Каждый инструмент звучит по-своему": "💡 Тоғра. Һәр бир сайман өзичә яңрайду",
"💡 Верно. Кюй — инструментальная музыка": "💡 Тоғра. Күй — инструментал музика",
"💡 Верно. Мотив — самая маленькая часть мелодии": "💡 Тоғра. Мотив — нахшиниң әң кичик қисми",
"💡 Верно. Музыку придумывают во время исполнения": "💡 Тоғра. Музикини ижра қилиш вақтида ойлап чиқиду",
"💡 Верно. Нотный стан — пять линеек": "💡 Тоғра. Нота сизиғи — бәш сизиқ",
