"💡 На кобызе играют смычком": "💡 Қобузда йәй билән чилиду",
"💡 Начинаем вместе по знаку": "💡 Бирликтә ишарәт бойичә башлаймиз",
"💡 Неверно. В ансамбле темп общий": "💡 Хата. Ансамбльда қарқин ортақ",
"Мяч — любимый снаряд игроков. Давай узнаем, что с ним можно делать. Нажимай на карточки.": "Топ — ойунчиларниң яхши көридиған снаряди. Униң билән немә қилишқа болидиғанлиғини билимиз. Карточкиларни бесиң.",
"Надевай удобную обувь, завязывай шнурки и слушай учителя.": "Қулайлиқ путқийим кий, бағлиғини бағла вә оқутқучини аңла.",
"Наклоны входят в разминку. Они разогревают спину и ноги.": "Энгишиш қизиш қисми. Улар арқа вә путларни қизитиду.",
"Начинают бег по сигналу. Время засекают секундомером.": "Чепишни сигнал бойичә башлайду. Вақитни секундомер билән өлчәйду.",
"Перед занятием тело нужно подготовить. Давай узнаем, как разминаться и как не получить травму. Нажимай на карточки.": "Маштин бурун тәнни тәйярлаш керәк. Қандақ қизиш вә җарақәт алмаслиқни билимиз. Карточкиларни бесиң.",
"Перетягивание каната — две команды тянут канат в разные стороны.": "Арқан тартиш — икки команда арқанни һәр хил тәрәпкә тартиду.",
"По гимнастической скамейке ходят, держа спину прямо и руки в стороны.": "Гимнастика орундуқида арқа түз, қоллар икки тәрәпкә ечилған һалда маңиду.",
"Победителя нужно поздравить, а проигравшего подбодрить.": "Ғалибни тәбриклиш, мәғлубни болса рәғбәтләндүрүш керәк.",
"Поздравляю! Ты узнал про здоровье, разминку, бег и прыжки, гимнастику, игры с мячом, национальные игры и честную командную игру. Теперь можно двигаться и играть каждый день!": "Тәбрикләймән! Сән саламәтлик, қизиш, чепиш вә секрәш, гимнастика, топ оюнлири, миллий оюнлар вә адил команда оюни һәққидә үгәндиң. Һазир һәр күни һәрикәт қилип ойнашқа болиду!",
"После бега мы дышим чаще. Это нормально.": "Чапқандин кейин тез-тез нәпәс алимиз. Бу нормал.",
"После игры полезно попить воды.": "Ойундин кейин су ичиш пайдилиқ.",
"После нагрузки идём спокойно и дышим ровно. Это заминка.": "Жүкләмидин кейин тинч маңимиз вә тәкши нәпәс алимиз. Бу арамлиқ.",
"При беге сердце бьётся быстрее, чтобы тело получило больше воздуха.": "Чапқанда жүрәк тез уриду, тән көпрәк һава алсун дәп.",
"При ведении мяч двигается рядом с игроком.": "Топни йетәкләшкәндә топ ойунчиниң йенида һәрикәтлиниду.",
"При метании замахиваются рукой и бросают предмет в цель.": "Ташлиғанда қолни силтап, нәрсини нишанға ташлайду.",
"При прыжке отталкиваются ногами. Приземляются на мягкие согнутые ноги.": "Секригәндә путлар билән түртүп чиқиду. Юмшақ егилгән путларға қонду.",
"Привет! Это Барсик. Движение делает нас сильными и здоровыми. Нажимай на карточки и узнавай, что происходит с телом.": "Салам! Бу Барсик. Һәрикәт бизни күчлүк вә саламәт қилиду. Карточкиларни бесип, тәнгә немә болидиғанлиғини билиң.",
"Приседания делают ноги сильнее.": "Олтирип-туруш путларни күчәйтиду.",
"Приседания разогревают ноги.": "Олтирип-туруш путларни қизитиду.",
"Проверим, что ты запомнил. Выбери верный ответ.": "Немини есиңдә тутқанлиғиңни тәкшүрәйли. Тоғра җаваб тал.",
"Прыжок в длину мерят от линии старта до места приземления.": "Узунлуққа секрәшни старт сизиғидин қонуш җайиғичә өлчәйду.",
"Разложи карточки по группам. Выбери, к какой группе относится каждая карточка.": "Карточкиларни топларға бөл. Һәр бир карточка қайси топқа тегишлик екәнлигини тал.",
"Разложи по группам": "Топларға бөл",
"Разминка согревает мышцы и помогает не получить травму.": "Қизиш мускулларни иситиду вә җарақәт алмаслиққа жардәмлишиду.",
"Салки, эстафеты с обручем и бег с флажками играют без мяча.": "Қоғлашмақ, тәгләрдә эстафета вә байрақчилиқ чепиш топсиз ойналиду.",
"Секундомер показывает, за сколько секунд ты пробежал.": "Секундомер сән нәччә секундта чапқанлиғиңни көрситиду.",
"Судья следит за правилами и подаёт сигнал свистком.": "Һәким қаидилиргә көз-қулақ болиду вә шилдирлақ билән сигнал бериду.",
