"💡 Бросовый материал — это то, что часто выбрасывают, например коробка или бутылка": "💡 Чиқинди материал — көп ташливетидиған нәрсә, мәсилән қута яки бөтилкә",
"💡 Бумагу можно порвать руками, а железо и камень нельзя": "💡 Қәғәзни қол билән йиртишқа болиду, төмүр вә ташни болмайду",
"💡 Бутылку моют и сушат": "💡 Бөтилкини жуюп, қурутиду",
"💡 В аппликации детали наклеивают на основу": "💡 Аппликацияда детальларни асасқа чаплайду",
"💡 Вежливая оценка помогает сделать лучше": "💡 Әдәплик баһа яхшилашқа жардәмлишиду",
"💡 Вежливый совет называет, что улучшить": "💡 Әдәплик мәслиһәт немини яхшилаш керәкликини ейтиду",
"💡 Верно. Вату легко мять": "💡 Тоғра. Пахтини асан мичишқа болиду",
"💡 Верно. Её можно использовать для поделки": "💡 Тоғра. Уни ясалмида қоллинишқа болиду",
"💡 Верно. Картон плотнее и прочнее": "💡 Тоғра. Картон зичрақ вә мустәһкәмрәк",
"💡 Верно. Книги и образцы дают идеи": "💡 Тоғра. Китаб вә үлгиләр идея бериду",
"💡 Верно. Материал описывают по цвету, форме и другим свойствам": "💡 Тоғра. Материални рәңги, шәкли вә башқа хусусийәтлири бойичә тәсвирләйду",
"💡 Верно. На выставке показывают поделки": "💡 Тоғра. Көргәзмидә ясалмилар көрситилиду",
"💡 Верно. Ноль — начало линейки": "💡 Тоғра. Нөл — линейканиң башлиниши",
"💡 Верно. Повтор создаёт орнамент": "💡 Тоғра. Тәкрар орнамент яритиду",
"💡 Верно. Порядок — это часть работы": "💡 Тоғра. Тәртип — ишниң бир қисми",
"💡 Верно. Рулеткой измеряют длинные расстояния": "💡 Тоғра. Рулетка билән узун арилиқларни өлчәйду",
"💡 Верно. Сухие листья не портятся": "💡 Тоғра. Қуруқ йопурмақлар бузулмайду",
"💡 Верно. Так линия получается ровной": "💡 Тоғра. Шундақ қилсақ сизиқ түз чиқиду",
"💡 Верно. Так никто не поранится": "💡 Тоғра. Шундақ қилсақ һечким җарақәт алмайду",
"💡 Верно. Так работа становится лучше": "💡 Тоғра. Шундақ қилсақ иш яхширақ болиду",
"💡 Верно. Фигурки складывают из бумаги": "💡 Тоғра. Шәкилләрни қәғәздин бүкләп ясайду",
"💡 Верно. Художники берут формы природы": "💡 Тоғра. Рәссамлар тәбиәтниң шәкиллирини елиду",
"💡 Верно. Чапан носят поверх одежды": "💡 Тоғра. Чапанни кийимниң үстидин кийиду",
"💡 Верно. Чистый материал удобнее в работе": "💡 Тоғра. Пак материал билән ишләш ыңғайлиқ",
"💡 Верно. Шаблон обводят карандашом": "💡 Тоғра. Шаблонни қарандаш билән сизип чиқиду",
"💡 Верно. Шишка растёт на дереве": "💡 Тоғра. Қарағай мевиси дәрәқтә өсиду",
"💡 Верно. Эскиз помогает продумать работу": "💡 Тоғра. Эскиз ишни ойлишишқа жардәмлишиду",
"💡 Верно. Эскиз рисуют до начала работы": "💡 Тоғра. Эскизни иш башлинишидин бурун сизиду",
"💡 Верно. Это войлочное изделие из овечьей шерсти": "💡 Тоғра. Бу қой жүнидин ясалған кигиз буюм",
"💡 Длинные расстояния меряют рулеткой": "💡 Узун арилиқларни рулетка билән өлчәйду",
"💡 Длину измеряют в сантиметрах": "💡 Узунлуқни сантиметрда өлчәйду",
"💡 Длину измеряют линейкой": "💡 Узунлуқни линейка билән өлчәйду",
"💡 Для прочной поделки нужен прочный материал": "💡 Мустәһкәм ясалма үчүн мустәһкәм материал керәк",
"💡 Живые цветы срывать нельзя": "💡 Тирик гүлләрни үзүшкә болмайду",
"💡 Жёлудь — плод дуба, он есть в природе": "💡 Бәлдағ — дәрәқ мевиси, у тәбиәттә бар",
"💡 Закрытые ножницы кладут на стол": "💡 Ябиқ қайчини столға қойиду",
"💡 Иглу хранят в игольнице, так она не потеряется": "💡 Игини игә қутисида сақлайду, шундақ қилсақ йоқалмайду",
"💡 Из деталей по плану собирают изделие": "💡 Детальлардин пилан бойичә буюм жиғиду",
"💡 Картон плотнее и прочнее бумаги": "💡 Картон қәғәздин зичрақ вә мустәһкәмрәк",
"💡 Кошму делают из свалянной овечьей шерсти": "💡 Кигизни тоқулған қой жүнидин ясайду",
"💡 Листья сушат под грузом между страницами книги": "💡 Йопурмақларни китаб бәтлири арисида жүк астида қурутиду",
"💡 На выставке показывают работы": "💡 Көргәзмидә ишлар көрситилиду",
