"💡 В графике рисуют линиями и штрихами, например карандашом": "💡 Графикида сизиқ вә штрихлар билән сизиду, мәсилән қарандаш билән",
"💡 В натюрморте рисуют предметы": "💡 Натюрмортта нәрсиләрни сизиду",
