"Алматы — самый большой город Казахстана. Он расположен на юго-востоке страны.": "Алмута — Қазақстанниң әң чоң шәһири. У дөләтниң җәнубий-шәрқидә җайлашқан.",
"Аль-Фараби был великим учёным": "Әл-Фараби бөюк алим еди",
"Аль-Фараби был великим учёным. Его называли «Вторым учителем». Он родился в Фарабе — так раньше называли город Отрар.": "Әл-Фараби бөюк алим еди. Уни «Иккинчи оқутқучи» дәп атиған. У Фарабта туғулған — бу бурун Отрар шәһири шундақ аталғанди.",
"Аль-Фараби был космонавтом": "Әл-Фараби космонавт еди",
"Аль-Фараби жил очень давно, больше тысячи лет назад": "Әл-Фараби жуда бурун, мың жилдин көпрәк бурун яшиған",
