"Ботай": "Ботай",
"Ботайская культура связана с приручением лошади": "Ботай мәдәнийити атни қолға көндүрүш билән бағлиқ",
"Ботайская культура — культура древних людей на севере Казахстана. Ботайцы считаются одними из первых в мире, кто приручил лошадь.": "Ботай мәдәнийити — Қазақстанниң шималидики қедимий кишиләрниң мәдәнийити. Ботайлиқлар дунйада атни қолға көндүргәнләрниң бири дәп һесаплиниду.",
"Бросить мусор на землю": "Йәргә чиқинди ташлаш",
"Бурабай": "Бурабай",
"Были кочевниками и разводили скот": "Көчмән болған вә мал бақти",
"В Акмолинской области": "Ақмола вилайитидә",
"В Алматы": "Алмутида",
"В Атырауской области": "Атирау вилайитидә",
