"В автобусе держись за поручень и уступай место пожилым людям. Не выбегай на дорогу и не высовывайся из окна.": "Автобуста тутқучқа тут вә яшанғанларға орун бәр. Йолға чиқип кәтмә вә дерезидин бешиңни чиқарма.",
"В автобусе можно высовывать руки из окна": "Автобуста қолни дерезидин чиқиришқа болиду",
"В горах Алтая": "Алтай тағлирида",
