"В город Туркестан": "Түркістан шәһиригә",
"В городе много интересного: магазины, транспорт, улицы. Давай узнаем, как питаться правильно и вести себя безопасно. Нажимай на карточки.": "Шәһәрдә қизиқарлиқ нәрсә көп: дукан, транспорт, кочилар. Қандақ дурус озуқлиниш вә бехәтәр өзини тутушни билимиз. Карточкиларни бесиң.",
"В горы Алатау": "Алатау тағлиригә",
"В группе все говорят одновременно": "Топта һәммиси бир вақитта сөзләйду",
"В группе слушают друг друга по очереди, распределяют роли и договариваются, кто что делает.": "Топта бир-бирини кезим-кезими билән аңлайду, роллар тарқитиду вә кимниң немә қилидиғанлиғини келишиду.",
"В декабре мы празднуем независимость страны. В День Победы вспоминают тех, кто защищал страну в Великой Отечественной войне.": "Декабрьда дөләтниң мустәқиллигини тәбриклаймиз. Ғәлибә күнидә Улуқ Ватәнийә урушида әлни қоғдиғанларни есимизгә алимиз.",
