"Где утром встаёт Солнце?": "Әтигән Қуяш қәйәрдин чиқиду?",
"Где-то жить удобно: тёплое лето, чистая река, плодородная земля. А где-то трудно: сильные ветры или мало воды.": "Бәзи җайда яшаш қулайлиқ: иссиқ яз, пак дәрия, түвлүк йәр. Бәзи җайда болса қийин: күчлүк шамал яки су аз.",
"Герб Казахстана — это изображение шанырака, тулпаров и звезды": "Қазақстан гербиси — шаңарақ, тулпарлар вә юлтуз тәсвири",
"Герб изображён на государственных документах, например на паспорте": "Герб дөләт һөҗҗәтлиридә, мәсилән паспортта тәсвирләнгән",
