"Гимн слушают стоя в знак уважения": "Гимнни һөрмәт бәлгүси сүпитидә турүп аңлайду",
"Гимн — торжественная песня страны. Его слушают стоя, так выражают уважение к стране.": "Гимн — әлниң тәнтәнилик нахшиси. Уни турүп аңлайду, шундақ қилип әлгә һөрмәт көрситиду.",
"Говорить правду": "Һәқиқәтни ейтиш",
"Говорить правду родным — хорошее семейное правило": "Туғқанларға һәқиқәтни ейтиш — яхши аилә қаидиси",
"Гололёд": "Муз",
"Голубым цветом": "Көк рәң билән",
"Горнолыжный курорт Шымбулак находится рядом с Алматы": "Шымбулақ тағ чаңғиси курорти Алмутиниң йенида",
"Горнолыжный курорт недалеко от Алматы": "Алмутидин йирақ әмәс тағ чаңғиси курорти",
"Город Туркестан известен мавзолеем Ходжи Ахмеда Ясави": "Түркістан шәһири Қожа Әһмәд Яссәвийниң мавзолейи билән мәшһур",
"Горы дают много пшеницы": "Тағлар буғдайни көп бериду",
"Государственные символы Казахстана — флаг, герб и гимн.": "Қазақстанниң дөләт символлири — байрақ, герб вә гимн.",
