"Достопримечательность — интересное место, которым гордятся жители. О нём можно рассказать, нарисовать его или сделать макет.": "Көрүмлүк җай — аһали пәхирлинидиған қизиқарлиқ җай. Униң һәққидә һекайә қилишқа, сизишқа яки макет ясашқа болиду.",
