"Как лучше всего узнать, что нужно твоей семье?": "Аилиңгә немә керәкликини билишниң әң яхши йоли қайси?",
"Как можно изобразить достопримечательность своего края?": "Өз өлкәңдики көрүмлүк җайни қандақ тәсвирләшкә болиду?",
"Как можно рассказать о своём классе?": "Өз синипиң һәққидә қандақ һекайә қилишқа болиду?",
