"Как по семейной фотографии составить словесный портрет бабушки?": "Аилә сүритигә қарап моминиң сөз билән портретини қандақ түзүш керәк?",
"Как показывают реки, озёра и моря на карте?": "Картида дәрия, көл вә деңизлар қандақ көрситилиду?",
