"Какая польза от гор для людей?": "Тағларниң кишиләргә қандақ пайдиси бар?",
"Какая у него машина": "Униң машинисиси қандақ",
"Какого цвета государственный флаг Казахстана?": "Қазақстан дөләт байриғи қандақ рәңдә?",
"Какого цвета парты в других классах": "Башқа синиплардики партилар қандақ рәңдә",
"Какое животное приручили люди Ботайской культуры?": "Ботай мәдәнийитиниң кишилири қайси һайванни қолға көндүргән?",
"Какой вид туризма выбрать, если хочешь кататься на лыжах?": "Чаңғида учушни халисаң, туризмниң қайси түрини таллайсән?",
