"Поезд": "Поезд",
"Поздравляю! Ты узнал про семью, школу, родной край, карту, город, права, погоду, путешествия, историю и символы Казахстана. Теперь закрепляй знания в играх.": "Тәбрикләймән! Сән аилә, мәктәп, туғулған өлкә, карта, шәһәр, һоқуқ, һава райи, сәйәһәтләр, тарих вә Қазақстан символлири һәққидә үгәндиң. Һазир билимлириңни ойунларда мустәһкәмлә.",
