"Поливать поля": "Етизларни суғириш",
"Получать помощь врача": "Врачтин ярдәм елиш",
"Помогает выбрать книгу и выдаёт её": "Китаб таллашқа жардәмлишиду вә уни бериду",
"Помогать по дому могут только взрослые": "Өйдә пәқәт чоңлар жардәмлишәләйду",
"Помогать соседям и убирать двор — это вклад в жизнь общества": "Қошниларға жардәмлишиш вә һойлини тазилаш — җәмийәт һаятиға қошқан һәссә",
"Помочь пожилому человеку донести сумку": "Яшанғанға сумкини көтүрүшкә жардәмлишиш",
"Понаблюдать и расспросить родных": "Күзитип, туғқанлардин сорап көрүш",
