"Посреди озера": "Көл оттурисида",
"Посреди тротуара": "Йолниң оттурисида",
"Почему яблоко полезнее конфет?": "Алма немигә конфеттин пайдилиқ?",
"Правде родные верят": "Һәқиқәткә туғқанлар ишиниду",
"Правила нужны всем, и ученик их выполняет": "Қаидиләр һәммигә керәк, оқуғучи уларни орундайду",
"Правила нужны только учителям, а ученикам не нужны": "Қаидиләр пәқәт оқутқучиларға керәк, оқуғучиларға керәк әмәс",
"Правила нужны, чтобы всем было удобно: не опаздывать, поднимать руку, беречь школьную мебель.": "Қаидиләр һәммигә қулайлиқ болуши үчүн керәк: кеч қалмаслиқ, қол көтириш, мәктәп мебелини асраш.",
"Правила помогают жить дружно: уважать старших, помогать друг другу, говорить правду.": "Қаидиләр иттипақ яшашқа жардәмлишиду: чоңларни һөрмәтләш, бир-биригә жардәмлишиш, һәқиқәтни ейтиш.",
"Право — это то, что положено каждому ребёнку: учиться, получать помощь врача, жить в семье.": "Һоқуқ — һәр бир балиға тегишлик нәрсә: оқуш, врачтин ярдәм елиш, аиләдә яшаш.",
"Праздники нужны, чтобы помнить важные события в истории страны": "Байрамлар дөләт тарихидики муһим вәқәләрни есләш үчүн керәк",
"При гололёде идут осторожно, маленькими шагами. Он мешает, но обычно не угрожает жизни.": "Муз вақтида әһтиятчанлиқ билән, кичик қәдәмләр билән маңиду. У тосалғу болиду, лекин адәттә һаятқа хәвп төвәндүрмәйду.",
"Привет! Это Барсик. Давай поговорим о семье: какие в ней правила, что семье нужно, а чего просто хочется. Нажимай на карточки.": "Салам! Бу Барсик. Аилә һәққидә сөзләшәйли: униңда қандақ қаидиләр бар, аилигә немә керәк, немә пәқәт халайду. Карточкиларни бесиң.",
"Признать ошибку и постараться исправить": "Хатани етирап қилип, түзитишкә тиришиш",
"Природный туризм: любуются природой, например Чарынским каньоном и Кольсайскими озёрами.": "Тәбиий туризм: тәбиәткә һаят қалиду, мәсилән Чарын каньонида вә Көлсай көллиридә.",
"Прыгать": "Секрәш",
