"Радуга после дождя": "Ямғурдин кейинки һалқа",
"Разведение домашних животных": "Өй һайванлирини көпәйтиш",
"Разведение животных": "Һайванларни көпәйтиш",
"Разведение овец и лошадей": "Қой вә ат көпәйтиш",
"Раньше люди брали у природы готовое: охотились, ловили рыбу, собирали ягоды и грибы.": "Илгири кишиләр тәбиәттин тәйярини алатти: овчилиқ қилатти, балиқ тутатти, мевә вә гүлханлиқ йиғатти.",
"Растаявший снег наполняет реки": "Йеринип кәткән қар дәриялирини толтуриду",
"Растения лучше всего растут там, где нет воды": "Өсүмлүкләр су болмиған йәрдә әң яхши өсиду",
"Река Урал течёт на западе и впадает в Каспийское море. Река Или впадает в озеро Балхаш.": "Орал дәрияси Қазақстанниң ғәрбидә еқип Каспий деңизиға қуйиду. Или дәрияси Балқаш көлигә қуйиду.",
"Реки дают воду для полей и электричество на гидроэлектростанциях. По ним плавают суда.": "Дәриялар етизлар үчүн су вә гидроелектростанцияләрдә электр қуввити бериду. Уларда кемиләр қатнайду.",
