"Туристы едут в музеи, чтобы узнавать новое": "Туристлар йеңилиқ билиш үчүн музейларға бариду",
"Туристы путешествуют, чтобы отдохнуть, узнать новое или заняться спортом. Давай отправимся в путешествие по Казахстану. Нажимай на карточки.": "Туристлар дема елиш, йеңилиқ билиш яки спорт билән шуғуллиниш үчүн сәйәһәт қилиду. Қазақстан бойичә сәйәһәткә чиқайли. Карточкиларни бесиң.",
