"Тёплое долгое лето": "Иссиқ узун яз",
"Тёплое солнце летом": "Яздики иссиқ қуяш",
"Тёплую одежду, воду и удобную обувь": "Иссиқ кийим, су вә қулайлиқ путқийим",
"Тёплый дождь весной": "Баһардики иссиқ ямғур",
