"У каждого края своя природа. Горы, равнины, реки и озёра помогают людям по-разному. Нажимай на карточки и узнавай.": "Һәр бир өлкиниң өз тәбиити бар. Тағ, түзләңлик, дәрия вә көл кишиләргә һәр хил жардәмлишиду. Карточкиларни бесип, билиң.",
"У каждого ребёнка есть право на образование": "Һәр бир балиниң билим елиш һоқуқи бар",
"У каждого ребёнка есть право учиться в школе": "Һәр бир балиниң мәктәптә оқуш һоқуқи бар",
"У каждого человека есть права и обязанности. Давай разберёмся, что это такое, и вспомним главные праздники страны. Нажимай на карточки.": "Һәр бир адәмниң һоқуқи вә мәсулийити бар. Буниң немә екәнлигини чүшинәйли вә әлниң асасий байрамлирини есимизгә алайли. Карточкиларни бесиң.",
"У каждой местности есть свои плюсы и свои трудности": "Һәр бир җайниң өз артуқчилиқи вә қийинчилиқи бар",
"У каждой семьи могут быть свои обычаи и правила": "Һәр бир аилиниң өз адәт вә қаидилири болиши мумкин",
"У каждой страны есть главные символы. Давай познакомимся с символами Казахстана. Нажимай на карточки.": "Һәр бир әлниң асасий символлири бар. Қазақстан символлири билән тонушайли. Карточкиларни бесиң.",
"У разных народов могут быть свои праздники и обычаи": "Һәр хил хәлиқләрниң өз байрам вә адәтлири болиши мумкин",
