"Ураган": "Боран",
"Ураган, буран и гроза с молнией — опасные явления. В грозу прячутся в доме, а не стоят под высоким деревом.": "Боран, қарборан вә чақмақлиқ күркирәш — хәтәрлик һадисәләр. Күркирәшта өйгә йошурунуду, бәләнт дәрәқ астида турулмайду.",
"Урок — это учебная деятельность": "Дәрис — оқуш паалийити",
"Уроки в школе": "Мәктәптики дәрисләр",
"Учителем танцев": "Усул оқутқучиси",
