"Флаг, герб и гимн называют государственными символами": "Байрақ, герб вә гимн дөләт символлири дәп атилиду",
"Характеристика класса — это рассказ о ребятах, об их интересах и правилах класса.": "Синипниң тәриплимиси — балилар, уларниң қизиқишлири вә синип қаидилири һәққидә һекайә.",
