"Что нужно взять в горный поход?": "Тағ сәйәһитигә немә елиш керәк?",
"Что нужно сделать, когда автобус тронулся, а ты стоишь?": "Автобус йүрүп кәткәндә, сән турсаң немә қилиш керәк?",
