"Школа — это место, где мы учимся и дружим. Давай узнаем, кто работает в школе и какие у нас правила. Нажимай на карточки.": "Мәктәп — биз оқуйдиған вә дост болидиған җай. Мәктәптә кимләр ишләйдиғанлиғини вә қандақ қаидилиримиз барлиғини биливетәйли. Карточкиларни бесиң.",
