"Чтобы быстро записывать, используют условные знаки: солнышко — ясно, облако — облачно, тучка с каплями — дождь, снежинка — снег.": "Тез йезиш үчүн шәртлик бәлгиләр ишлитилиду: қуяшчә — ечиқ, булут — булутлуқ, тамчилиқ булут — ямғур, қар учқуни — қар.",
