"все они связаны между собой, исчезновение одних вредит другим": "улар һәммиси бир-бири билән бағлиқ, бәзилириниң йоқилиши башқилириға зиян йәткүзиду",
"всегда лить воду зря": "һәмишә суни бекар қуюш",
"всего один день": "пәқәт бир күн",
"всё небо закрыто облаками": "пүткүл асман булут билән қапланған",
"всё связано": "һәммә нәрсә бағлиқ",
"выбрасываем таблицу": "җәдвәлни ташлаймиз",
"выбрасывает свою запись": "өз йезиғини ташливетиду",
"выбросить дневник": "күндиликни ташлаш",
"вывод": "хуласә",
"выключить лампу": "чирақни өчүрүш",
"вырастет быстрее всех": "һәммидин тез өсиду",
"вырастет выше": "егизирәк өсиду",
"вытаптывают": "дәссәйду",
"вытираются своим чистым полотенцем": "өзиниң таза сөлигиси билән сүртүниду",
"выходит из икры": "уруқтин чиқиду",
"газ": "газ",
"газообразном": "газсиман",
"гиганты": "гигантлар",
"гигиена": "гигиена",
"гипотеза": "гипотеза",
"глубокие корни и мелкие листья или колючки": "чоңқур йилтиз вә майда япрақ яки тикәнләр",
"головастик": "бақа балиси",
"головастики": "бақа балилири",
"голубая": "көк",
"горячий чай": "иссиқ чай",
"громкие": "қаттиқ",
"громкий": "қаттиқ",
"громкий голос": "қаттиқ аваз",
"гусеницы": "қуртлар",
"да, мороз им полезен": "һә, соғуқ уларға пайдилиқ",
