"Какая клавиша нужна?: Как вставить скопированный текст с клавиатуры?": "Қайси клавиш керәк?: Көчүрүлгән тексттни клавиатурадин қандақ қоюш керәк?",
"Какая клавиша нужна?: Как скопировать выделенный текст с клавиатуры?": "Қайси клавиш керәк?: Бөлүп елинған тексттни клавиатурадин қандақ көчүрүш керәк?",
"Какая клавиша нужна?: Какая клавиша находится длинной полосой внизу клавиатуры?": "Қайси клавиш керәк?: Клавиатуриниң түвидики узун сизиқ қайси клавиш?",
