"Какая клавиша нужна?: Нужно напечатать слово с заглавной буквы. Что нажать вместе с буквой?": "Қайси клавиш керәк?: Сөзни чоң һәрип билән йезиш керәк. Һәрип билән немини бесиш керәк?",
"Какая клавиша нужна?: Нужно передвинуть курсор вправо. Что нажать?": "Қайси клавиш керәк?: Курсорни оңға жутуш керәк. Немини бесиш керәк?",
"Какая клавиша нужна?: Нужно перейти на новую строку. Что нажать?": "Қайси клавиш керәк?: Йеңи қатарға өтүш керәк. Немини бесиш керәк?",
"Какая клавиша нужна?: Нужно сделать промежуток между словами. Что нажать?": "Қайси клавиш керәк?: Сөзләр арисида бош орун қелиш керәк. Немини бесиш керәк?",
"Какая клавиша нужна?: Нужно стереть букву слева от курсора. Что нажать?": "Қайси клавиш керәк?: Курсорниң солидики һәрипни өчүрүш керәк. Немини бесиш керәк?",
"Какая клавиша нужна?: Нужно стереть букву справа от курсора. Что нажать?": "Қайси клавиш керәк?: Курсорниң оңидики һәрипни өчүрүш керәк. Немини бесиш керәк?",
"Какое слово стоит в записи алгоритма ветвления?": "Тармақлиниш алгоритмини йезишта қайси сөз туриду?",
"Какое устройство входит в устройства ввода?": "Қайси қурулма киргүзүш қурулмилириға кириду?",
"Какое устройство нужно?: Какое устройство передаёт информацию в компьютер?": "Қайси қурулма керәк?: Қайси қурулма мәлуматни компьютерға йәткүзиду?",
"Какое устройство нужно?: Какое устройство только показывает информацию?": "Қайси қурулма керәк?: Қайси қурулма пәқәт мәлуматни көрситиду?",
"Какое устройство нужно?: Нужно выбрать картинку на экране. Что использовать?": "Қайси қурулма керәк?: Экрандики сүрәтни таллаш керәк. Немини ишлитиш керәк?",
"Какое устройство нужно?: Нужно записать свой голос. Что использовать?": "Қайси қурулма керәк?: Өз авазиңни йезиш керәк. Немини ишлитиш керәк?",
"Какое устройство нужно?: Нужно напечатать слово. Что использовать?": "Қайси қурулма керәк?: Сөзни йезиш керәк. Немини ишлитиш керәк?",
